package org.apache.commons.math.util;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.math.exception.DimensionMismatchException;
import org.apache.commons.math.exception.NotStrictlyPositiveException;
import org.apache.commons.math.exception.OutOfRangeException;
import org.apache.commons.math.util.MathUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for MultidimensionalCounter#getCounts
 */
public class MultidimensionalCounter_getCounts_TriageGen0Test {

    @Test
    public void testGetCounts_OutOfBoundsLow() {
        MultidimensionalCounter counter = new MultidimensionalCounter(2, 3);
        try {
            counter.getCounts(-1);
            fail("Expected OutOfRangeException for index < 0");
        } catch (OutOfRangeException e) {
            // Expected
        }
    }

    @Test
    public void testGetCounts_OutOfBoundsHigh() {
        MultidimensionalCounter counter = new MultidimensionalCounter(2, 3);
        int totalSize = counter.getSize();
        try {
            counter.getCounts(totalSize);
            fail("Expected OutOfRangeException for index >= totalSize");
        } catch (OutOfRangeException e) {
            // Expected
        }
    }

    @Test
    public void testGetCounts_DimensionOne() {
        // For dimension 1, last = 0. Loop i from -1 to < 0 won't execute.
        // indices[0] = index - count (where count is 0)
        MultidimensionalCounter counter = new MultidimensionalCounter(5);

        assertArrayEquals(new int[]{0}, counter.getCounts(0));
        assertArrayEquals(new int[]{2}, counter.getCounts(2));
        assertArrayEquals(new int[]{4}, counter.getCounts(4));
    }

    @Test
    public void testGetCounts_DimensionTwo() {
        // Sizes: 2, 3. Total size = 6.
        // uniCounterOffset calculation logic (inferred from MultidimensionalCounter implementation):
        // For dim 2: offset[0] = 3, offset[1] = 1 (implied)
        MultidimensionalCounter counter = new MultidimensionalCounter(2, 3);

        // index 0: [0, 0]
        assertArrayEquals(new int[]{0, 0}, counter.getCounts(0));

        // index 1: [0, 1]
        assertArrayEquals(new int[]{0, 1}, counter.getCounts(1));

        // index 2: [0, 2]
        assertArrayEquals(new int[]{0, 2}, counter.getCounts(2));

        // index 3: [1, 0]
        assertArrayEquals(new int[]{1, 0}, counter.getCounts(3));

        // index 4: [1, 1]
        assertArrayEquals(new int[]{1, 1}, counter.getCounts(4));

        // index 5: [1, 2]
        assertArrayEquals(new int[]{1, 2}, counter.getCounts(5));
    }

    @Test
    public void testGetCounts_DimensionThree() {
        // Sizes: 2, 2, 2. Total size = 8.
        MultidimensionalCounter counter = new MultidimensionalCounter(2, 2, 2);

        // index 0: [0, 0, 0]
        assertArrayEquals(new int[]{0, 0, 0}, counter.getCounts(0));

        // index 1: [0, 0, 1]
        assertArrayEquals(new int[]{0, 0, 1}, counter.getCounts(1));

        // index 2: [0, 1, 0]
        assertArrayEquals(new int[]{0, 1, 0}, counter.getCounts(2));

        // index 3: [0, 1, 1]
        assertArrayEquals(new int[]{0, 1, 1}, counter.getCounts(3));

        // index 4: [1, 0, 0]
        assertArrayEquals(new int[]{1, 0, 0}, counter.getCounts(4));

        // index 7: [1, 1, 1]
        assertArrayEquals(new int[]{1, 1, 1}, counter.getCounts(7));
    }

    @Test
    public void testGetCounts_EdgeCaseSingleElement() {
        MultidimensionalCounter counter = new MultidimensionalCounter(1, 1, 1);
        assertArrayEquals(new int[]{0, 0, 0}, counter.getCounts(0));
    }
}
